// CSD_RATIONALE_BEGIN
// Best result (attempt 43, 52% accuracy, 99% syntax) used RenderedEndsWith +
// IsCompletePrefix early-close + GroupBoostedConstrainedStep(6.0). Root-cause of
// the remaining 48% failure: 141/300 are syntax-valid but semantically wrong
// (hallucinated table/column names, missing FROM/JOIN clauses, wrong aggregations).
//
// This attempt replaces the manual GroupBoostedConstrainedStep loop with
// RegenerateUnitOnGroundingFailure, which explicitly checks if identifier-like
// tokens (table names, column names) appear in the prompt context (= schema).
// When an ungrounded identifier is detected it rolls back to the last accepted
// checkpoint and resamples with the rejected identifier penalised, directly
// fixing hallucinated table/column names.
//
// Structure:
//   Phase 1 (≤5 steps): unconstrained preamble for "SQL: " prefix
//   Phase 2 (1 step):   force OpenConstrainedSpan if not entered naturally
//   Phase 3 (budget-50 steps): RegenerateUnitOnGroundingFailure – grounded SQL
//   Phase 4 (≤50 steps): close span (immediate if IsCompletePrefix, else
//                          CloseSpanWithinBudget for the longest complete point)
//
// Better guidance explicitly forbids table aliases and demands FROM clause so
// the model's free-text reasoning before entering the span is aligned.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 preamble loop: The guard includes !insideConstrainedOut, so the
//   implication body is never reached inside the loop. insideConstrainedOut
//   flips true only when RenderedEndsWith fires, at which point we set
//   currentConstrainedOut := [] and IsValidPrefix([]) holds by the method
//   precondition. EOS break leaves insideConstrainedOut false; implication is
//   vacuous.
//
//   Phase 2 (OpenConstrainedSpan): runs only when !insideConstrainedOut. The
//   helper sets currentConstrainedOut := []; IsValidPrefix([]) holds.
//
//   Phase 3 (RegenerateUnitOnGroundingFailure): postcondition guarantees
//   resultConstrained is always parser-valid. After
//   currentConstrainedOut := resultConstrained the invariant holds. The helper
//   only runs when insideConstrainedOut is true, so the implication is active;
//   its postcondition provides exactly the required parser-validity predicate.
//
//   Phase 4a (CloseConstrainedSpan): sets insideConstrainedOut := false, making
//   the implication vacuously true; also sets currentConstrainedOut := [].
//   Phase 4b (CloseSpanWithinBudget): postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut) and
//   !insideOut ==> currentOut == [].
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
//   Phase 1: each iteration increments steps by 1 and appends 0 (EOS) or 1
//   token; invariant preserved per iteration.
//
//   Phase 2: steps += 1, OpenConstrainedSpan appends exactly 1 "<<" token;
//   net 1:1 ratio, invariant preserved.
//
//   Phase 3: Let stablePrefix = generated_before[..|generated_before| -
//   |currentConstrainedOut_before|]. Then |stablePrefix| =
//   |generated_before| - |currentConstrainedOut_before|. After the update,
//   |generated_after| = |stablePrefix| + |resultConstrained|.
//   RegenerateUnitOnGroundingFailure costs at most +genBudget steps, so
//   |resultConstrained| <= |currentConstrainedOut_before| + genBudget.
//   Therefore |generated_after| <= |generated_before| + genBudget =
//   |generatedPrefix| + steps_before + genBudget = |generatedPrefix| +
//   steps_after. ✓
//
//   Phase 4a: CloseConstrainedSpan appends at most 1 ">>" token, steps += 1;
//   net ≤ 1:1 ratio. ✓
//   Phase 4b: CloseSpanWithinBudget postcondition guarantees
//   |generatedOut| <= |generated| + closeBudget; steps += closeBudget. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate a SQL SELECT query. CRITICAL RULES: (1) ALWAYS include FROM clause with the exact table name from the schema. (2) NEVER use table aliases — write the full table name everywhere. (3) Use ONLY the exact column and table names that appear in the schema. (4) Include WHERE, GROUP BY, HAVING, ORDER BY, LIMIT clauses when the question requires them. (5) For counting rows use COUNT(*). (6) For queries spanning multiple tables write: FROM t1 JOIN t2 ON t1.col = t2.col. Output only the SQL query between << and >>.");

var steps: nat := 0;

// Phase 1: Unconstrained preamble (at most 5 steps) for "SQL: " text
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside a constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Schema-grounded constrained SQL generation via
// RegenerateUnitOnGroundingFailure. Reserve 50 steps for span close.
if insideConstrainedOut && steps < maxSteps {
  var reserveClose: nat := 50;
  var genBudget: nat;
  if maxSteps - steps > reserveClose {
    genBudget := maxSteps - steps - reserveClose;
  } else {
    genBudget := 0;
  }
  if genBudget > 0 {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var rollbackBudget: nat := genBudget / 4;
    var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken,
      genBudget, 3, rollbackBudget
    );
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    generated := stablePrefix + resultConstrained;
    currentConstrainedOut := resultConstrained;
    steps := steps + genBudget;
  }
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat := if remaining <= 50 then remaining else 50;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

